function injuryOrder(a,b){return a.timestamp&&b.timestamp?new Date(b.timestamp)-new Date(a.timestamp):a.timestamp?-1:b.timestamp?1:new Date(b.sortAt||0)-new Date(a.sortAt||0)}function injuryFeedFrom(items,cap){const best=new Map;return[...items].sort((a,b)=>Number(b.fromClubArticle)-Number(a.fromClubArticle)||injuryOrder(a,b)).forEach(it=>{const key=it.clubId!=null?`id:${it.clubId}`:`name:${it.source||""}`;best.has(key)||best.set(key,it)}),[...best.values()].sort(injuryOrder).slice(0,cap)}function injuryStories(rows,teamsById){const byUrl=new Map;for(const r of rows)!r.url||!r.player||r.injuryArticle!==!1&&(byUrl.has(r.url)||byUrl.set(r.url,[]),byUrl.get(r.url).push(r));const out=[];for(const[url,group]of byUrl){const first=group[0],club=first.club||"",who=group.map(r=>r.injury?`${r.player} (${r.injury})`:r.player).join(", "),titled=!!first.articleTitle;out.push({category:"injury",categoryLabel:"Injury news",fromClubArticle:titled,headline:titled?first.articleTitle:who,detail:titled?club?`${club} \xB7 ${who}`:who:`${club?club+" \xB7 ":""}listed on the Premier League's injury table`,link:url,thumbnail:first.image||null,source:club,badge:null,isSquad:!1,timestamp:first.published||null,sortAt:first.published||first.firstSeen||null,matchedTeamIds:first.clubId!=null?[first.clubId]:[],clubId:first.clubId!=null?first.clubId:null,clubCode:first.clubId!=null&&teamsById[first.clubId]?teamsById[first.clubId].code:null,injuredPlayers:group.map(r=>r.player),playerIds:group.map(r=>r.playerId).filter(id=>id!=null),sortWeight:5})}return out}
